BEGIN;
CREATE TYPE care_plan_status AS ENUM ('ACTIVE','PAUSED','ENDED');
CREATE TYPE care_frequency AS ENUM ('MONTHLY','QUARTERLY','HALF_YEARLY','ANNUALLY','CUSTOM');
CREATE TYPE care_meeting_status AS ENUM ('PLANNED','CONFIRMED','COMPLETED','CANCELLED','NO_SHOW');
CREATE TYPE follow_up_status AS ENUM ('OPEN','IN_PROGRESS','COMPLETED','CANCELLED');
CREATE TABLE client_care_plans(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,client_id bigint NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,advisor_id bigint NOT NULL REFERENCES users(id) ON DELETE RESTRICT,status care_plan_status NOT NULL DEFAULT 'ACTIVE',frequency care_frequency NOT NULL DEFAULT 'HALF_YEARLY',custom_frequency_months integer,money_review_months integer,safety_review_months integer,rebalancing_review_months integer,goals_review_months integer,next_review_at timestamptz,notes text,created_by bigint NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK((frequency='CUSTOM' AND custom_frequency_months BETWEEN 1 AND 120) OR (frequency<>'CUSTOM' AND custom_frequency_months IS NULL)));
CREATE UNIQUE INDEX uq_client_active_care_plan ON client_care_plans(client_id) WHERE status='ACTIVE';
CREATE TABLE client_care_meetings(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,care_plan_id bigint NOT NULL REFERENCES client_care_plans(id) ON DELETE RESTRICT,client_id bigint NOT NULL REFERENCES clients(id),advisor_id bigint NOT NULL REFERENCES users(id),meeting_type text NOT NULL,channel text NOT NULL DEFAULT 'PERSONAL',status care_meeting_status NOT NULL DEFAULT 'PLANNED',scheduled_at timestamptz NOT NULL,completed_at timestamptz,money_case_id bigint REFERENCES money_cases(id) ON DELETE SET NULL,safety_case_id bigint REFERENCES safety_cases(id) ON DELETE SET NULL,rebalancing_plan_id bigint REFERENCES money_rebalancing_plans(id) ON DELETE SET NULL,summary text,next_meeting_at timestamptz,created_by bigint NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'COMPLETED' OR completed_at IS NOT NULL));
CREATE TABLE client_care_follow_ups(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,client_id bigint NOT NULL REFERENCES clients(id),advisor_id bigint NOT NULL REFERENCES users(id),care_plan_id bigint REFERENCES client_care_plans(id) ON DELETE SET NULL,meeting_id bigint REFERENCES client_care_meetings(id) ON DELETE SET NULL,money_case_id bigint REFERENCES money_cases(id) ON DELETE SET NULL,safety_case_id bigint REFERENCES safety_cases(id) ON DELETE SET NULL,title text NOT NULL,due_at timestamptz NOT NULL,status follow_up_status NOT NULL DEFAULT 'OPEN',completed_at timestamptz,created_by bigint NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK(status<>'COMPLETED' OR completed_at IS NOT NULL));
CREATE TABLE client_care_feedback(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,meeting_id bigint NOT NULL UNIQUE REFERENCES client_care_meetings(id) ON DELETE CASCADE,client_id bigint NOT NULL REFERENCES clients(id),satisfaction_rating smallint CHECK(satisfaction_rating BETWEEN 1 AND 5),clarity_rating smallint CHECK(clarity_rating BETWEEN 1 AND 5),service_rating smallint CHECK(service_rating BETWEEN 1 AND 5),comment text,would_recommend boolean,created_at timestamptz NOT NULL DEFAULT now());
COMMIT;
